// Itens cujo nome muda com o idioma; os demais usam o próprio TechName como rótulo
export const TECH_LABEL_KEYS: Partial<Record<TechName, keyof typeof translations["en"]>> = {
  AIOrchestration: "skillAiOrchestration",
}

export function techLabel(name: TechName, t: (key: keyof typeof translations["en"]) => string) {
  const key = TECH_LABEL_KEYS[name]
  return key ? t(key) : name
}

export function TechIcon({ name }: { name: TechName }) {
  const Icon = ICONS[name]
  return <Icon />
}
